  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Bazedoxifene has ~6% absolute oral bioavailability in humans, but this low F is driven by extensive phenolic glucuronidation; the query lacks phenolic hydroxyls, so this mechanism does not transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Raloxifene has ~2% human oral bioavailability due to glucuronidation of phenolic groups and high first-pass metabolism; the query has no phenol and a different metabolic scaffold, limiting transfer of this low-F mechanism.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C27"],
      "claim": "Tolperisone has very low human oral bioavailability due to rapid first-pass metabolism of its piperidine ketone motif; the query is a 4-anilinoquinazoline acrylamide with distinct metabolic handling.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C21"],
      "claim": "Avanafil shows 8–10% human bioavailability, but it belongs to a different heteroaromatic class; the query is a 4-anilinoquinazoline EGFR inhibitor known to be orally bioavailable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is dacomitinib, a 4-anilinoquinazoline EGFR inhibitor with reported absolute oral bioavailability well above 20% (approximately 80%). The provided low-F analogues are mechanistically distinct—phenolic glucuronidation, prodrug instability, or unrelated scaffolds—and do not override the known high oral bioavailability of this drug class.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query is included in the supplied evidence.",
    "The low-F analogues lack the quinazoline acrylamide core and their low bioavailability mechanisms are not transferable to the query.",
    "External knowledge of dacomitinib's high oral bioavailability is not represented in the provided experimental records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

